package com.movieticket.repository; import com.movieticket.entity.Show; import org.springframework.data.jpa.repository.JpaRepository; import java.time.LocalDate; import java.util.List; public interface ShowRepository extends JpaRepository<Show,Long>{List<Show> findByMovieMovieIdAndShowDateGreaterThanEqualOrderByShowDateAscShowTimeAsc(Long movieId,LocalDate date); List<Show> findAllByOrderByShowDateAscShowTimeAsc();}
